/**
 * The next Option can have an unlimited number of optional arguments.
 *
 * @return the OptionBuilder instance
 */
public static OptionBuilder hasOptionalArgs() {
    argCount = Option.UNLIMITED_VALUES;
    optionalArg = true;
    return INSTANCE;
}
